// Testbench for the light gun device (and the mouse read range) in HPS2PAD (rtl/hps2pad.sv).
// Drives the real HPS2PAD with the player bus waveform generated by MADAM_PLAYER:
// PBCLK high for 8 lines, low for 8 lines, then 8 clock pulses per line, data
// sampled by the console two CE ticks after the falling edge.
// Run: sim/run_tb.sh tb_hps2pad

`timescale 1ns/1ps

module tb_hps2pad;

	localparam LINE_TICKS = 1560;
	localparam NBITS = 96;

	reg         CLK = 0;
	reg         RST = 1;
	reg         CE = 0;
	reg         PBCLK = 0;
	reg         PBDOUT = 1;
	wire        PBDIN;

	reg  [ 2:0] PAD_SEL = 0;
	reg  [ 1:0] ARCADE_SEL = 0;
	reg         STICK_EN = 0;
	reg         MOUSE_EN = 0;
	reg  [ 1:0] GUN_SEL = 0;
	reg         GUN_PAL = 0;
	reg  [24:0] ps2_mouse = 0;
	reg         ARCADE_SERVICE = 0;
	reg  [12:0] joystick_0 = 0, joystick_1 = 0, joystick_2 = 0, joystick_3 = 0;
	reg  [ 7:0] joy0_x0 = 0, joy0_y0 = 0, joy0_x1 = 0, joy0_y1 = 0;
	reg  [ 7:0] joy1_x0 = 0, joy1_y0 = 0, joy1_x1 = 0, joy1_y1 = 0;

	wire [ 8:0] GUN_X, GUN_Y;
	wire        GUN_ON;

	integer errors = 0;
	integer checks = 0;

	always #5 CLK = ~CLK;
	always @(posedge CLK) CE <= ~CE;

	HPS2PAD dut
	(
		.CLK(CLK),
		.RST(RST),
		.CE(CE),

		.PBDIN(PBDIN),
		.PBDOUT(PBDOUT),
		.PBCLK(PBCLK),

		.EXPBDIN(1'b1),
		.EXPBDOUT(),

		.PAD_SEL(PAD_SEL),
		.ARCADE_SEL(ARCADE_SEL),
		.STICK_EN(STICK_EN),
		.MOUSE_EN(MOUSE_EN),
		.GUN_SEL(GUN_SEL),
		.GUN_PAL(GUN_PAL),
		.ARCADE_SERVICE(ARCADE_SERVICE),

		.joystick_0(joystick_0),
		.joystick_1(joystick_1),
		.joystick_2(joystick_2),
		.joystick_3(joystick_3),
		.joy0_x0(joy0_x0),
		.joy0_y0(joy0_y0),
		.joy0_x1(joy0_x1),
		.joy0_y1(joy0_y1),
		.joy1_x0(joy1_x0),
		.joy1_y0(joy1_y0),
		.joy1_x1(joy1_x1),
		.joy1_y1(joy1_y1),
		.ps2_mouse(ps2_mouse),

		.GUN_X(GUN_X),
		.GUN_Y(GUN_Y),
		.GUN_ON(GUN_ON)
	);

	// one bus tick = one CE period
	task tick(input integer n);
		integer i;
		begin
			for (i = 0; i < n; i = i + 1) begin
				@(posedge CLK);
				while (!CE) @(posedge CLK);
			end
		end
	endtask

	// One field of player bus activity, returns the first NBITS bits of the chain, MSB first
	reg [NBITS-1:0] rx;
	task frame;
		integer b, h;
		begin
			rx = '0;
			PBCLK = 1; tick(8*LINE_TICKS);
			PBCLK = 0; tick(8*LINE_TICKS);
			b = 0;
			while (b < NBITS) begin
				// line: rise at 100,300,..1500, fall at 200,400,..1400,1559
				tick(99);
				for (h = 0; h < 8 && b < NBITS; h = h + 1) begin
					PBCLK = 1; tick(h == 7 ? 59 : 100);
					PBCLK = 0; tick(2);
					rx = {rx[NBITS-2:0], PBDIN};
					b = b + 1;
					if (h != 7) tick(98);
				end
				tick(2);
			end
			PBCLK = 0; tick(8*LINE_TICKS);
		end
	endtask

	// Reference pixel for an aim: Main_MiSTer gives the calibrated screen as
	// -127..+127 (-128 only as a clamp), the screen is the VE window, framebuffer
	// pixels 0..319 x 0..239 in NTSC and PAL; nearest pixel, -127 the first,
	// +127 the last
	function automatic integer ref_px(input integer a, input integer last);
		real t;
		begin
			if (a < -127) a = -127;
			t = (a + 127) * last / 254.0;
			ref_px = $rtoi(t + 0.5);
		end
	endfunction

	// Reference: the count Portfolio's light gun driver decodes back to the pixel
	// (lightgun.h scan constants), both divisions rounded up
	function automatic [19:0] ref_counter(input integer ax, input integer ay);
		integer w, xs, ys, off, x, y, c;
		begin
			w   = GUN_PAL ? 388 : 320;
			xs  = GUN_PAL ? 1051 : 1030;
			ys  = GUN_PAL ? 12796 : 12707;
			off = GUN_PAL ? 58995 : 12835;
			x = ref_px(ax, 319);
			y = ref_px(ay, 239);
			c = ((y * ys) + ((x * xs * 10 + w - 1) / w) + 9) / 10;
			ref_counter = (c + off) & 20'hFFFFF;
		end
	endfunction

	// Portfolio's decoding of a count: the pixel it gives back
	task automatic decode(input [19:0] cnt, output integer x, output integer y);
		integer w, xs, ys, off, c10;
		begin
			w   = GUN_PAL ? 388 : 320;
			xs  = GUN_PAL ? 1051 : 1030;
			ys  = GUN_PAL ? 12796 : 12707;
			off = GUN_PAL ? 58995 : 12835;
			c10 = (cnt - off) * 10;
			y = c10 / ys;
			x = ((c10 % ys) * w) / (xs * 10);
		end
	endtask

	function automatic [7:0] to_axis(input integer a);
		to_axis = a;
	endfunction

	// the aim settles, then the pixel the driver decodes from the count
	task automatic aim_decode(input integer ax, input integer ay, output integer x, output integer y);
		begin
			joy0_x0 = to_axis(ax);
			joy0_y0 = to_axis(ay);
			repeat (130) @(posedge CLK);
			#1;
			decode(dut.lg_count, x, y);
		end
	endtask

	task automatic check_pixel(input integer ax, input integer ay, input integer ex, input integer ey, input [255:0] name);
		integer x, y;
		begin
			aim_decode(ax, ay, x, y);
			checks = checks + 1;
			if (x !== ex || y !== ey) begin
				errors = errors + 1;
				$display("FAIL %0s pal=%0d aim %0d,%0d: decodes to %0d,%0d expected %0d,%0d", name, GUN_PAL, ax, ay, x, y, ex, ey);
			end
		end
	endtask

	// the crosshair is shown when a gun is on the bus: the arcade gun, or the
	// home gun with at most 2 pads
	task automatic check_on(input exp, input [255:0] name);
		begin
			checks = checks + 1;
			if (GUN_ON !== exp) begin
				errors = errors + 1;
				$display("FAIL GUN_ON %0s: got %b expected %b", name, GUN_ON, exp);
			end
		end
	endtask

	function automatic [15:0] ref_pad(input [12:0] j);
		ref_pad = {1'b1, 2'b00, j[2], j[3], j[0], j[1], j[4], j[5], j[6], j[7], j[8], j[9], j[10], 2'b00};
	endfunction

	task check(input [NBITS-1:0] exp, input [255:0] name);
		begin
			checks = checks + 1;
			if (rx !== exp) begin
				errors = errors + 1;
				$display("FAIL %0s: got %h expected %h", name, rx, exp);
			end
		end
	endtask

	localparam BTN_A = 13'h0010, BTN_B = 13'h0020, BTN_C = 13'h0040, BTN_START = 13'h0800, BTN_COIN = 13'h1000;

	integer ux, uy, i, pal, px, py, dx, dy;
	reg [19:0] cnt;
	reg [39:0] gun;
	initial begin
		tick(10);
		RST = 0;
		tick(10);

		// 1. count of the implementation against the reference for every aim value,
		//    NTSC and PAL, and the pixel the driver decodes from it (exact), then the
		//    screen edges and the middle by value, and the aim reaching every edge
		//    pixel row and column in order
		GUN_SEL = 1;
		for (pal = 0; pal < 2; pal = pal + 1) begin
			GUN_PAL = pal[0];
			for (ux = -128; ux < 128; ux = ux + 1) begin
				for (uy = -128; uy < 128; uy = uy + 1) begin
					aim_decode(ux, uy, dx, dy);
					checks = checks + 1;
					if (dut.lg_count !== ref_counter(ux, uy)) begin
						errors = errors + 1;
						if (errors < 20) $display("FAIL counter pal=%0d aim %0d,%0d: got %0d expected %0d", pal, ux, uy, dut.lg_count, ref_counter(ux, uy));
					end
					px = ref_px(ux, 319);
					py = ref_px(uy, 239);
					checks = checks + 1;
					if (dy !== py || dx !== px) begin
						errors = errors + 1;
						if (errors < 20) $display("FAIL decode pal=%0d pixel %0d,%0d decodes to %0d,%0d", pal, px, py, dx, dy);
					end
					// the crosshair position is the pixel the count encodes
					checks = checks + 1;
					if (GUN_X !== px || GUN_Y !== py) begin
						errors = errors + 1;
						if (errors < 20) $display("FAIL crosshair pal=%0d aim %0d,%0d: GUN_X,GUN_Y %0d,%0d expected %0d,%0d", pal, ux, uy, GUN_X, GUN_Y, px, py);
					end
				end
			end
			check_pixel(-127, -127,   0,   0, "top left");
			check_pixel(-128, -128,   0,   0, "clamped top left");
			check_pixel( 127, -127, 319,   0, "top right");
			check_pixel(-127,  127,   0, 239, "bottom left");
			check_pixel( 127,  127, 319, 239, "bottom right");
			check_pixel(   0,    0, 160, 120, "middle");
			// moving right along a row: x never goes back, never jumps more than 2, y stays
			px = -1;
			for (ux = -127; ux < 128; ux = ux + 1) begin
				aim_decode(ux, 0, dx, dy);
				checks = checks + 1;
				if (dy !== 120 || dx < px || dx > px + 2 || (ux == -127 && dx != 0)) begin
					errors = errors + 1;
					$display("FAIL row pal=%0d aim %0d: %0d,%0d after x=%0d", pal, ux, dx, dy, px);
				end
				px = dx;
			end
			py = -1;
			for (uy = -127; uy < 128; uy = uy + 1) begin
				aim_decode(0, uy, dx, dy);
				checks = checks + 1;
				if (dx !== 160 || dy < py || dy > py + 1 || (uy == -127 && dy != 0)) begin
					errors = errors + 1;
					$display("FAIL column pal=%0d aim %0d: %0d,%0d after y=%0d", pal, uy, dx, dy, py);
				end
				py = dy;
			end
			$display("counter sweep pal=%0d done, errors=%0d", pal, errors);
		end
		GUN_PAL = 0;

		// 2. gun alone on the bus, grid of aim points incl. corners, trigger alternating
		PAD_SEL = 0;
		for (i = 0; i < 25; i = i + 1) begin
			ux = (i % 5) * 63 - 127 + ((i % 5) == 4 ? 2 : 0);
			uy = (i / 5) * 63 - 127 + ((i / 5) == 4 ? 2 : 0);
			joy0_x0 = to_axis(ux);
			joy0_y0 = to_axis(uy);
			joystick_0 = i[0] ? BTN_A : 13'd0;
			frame();
			cnt = ref_counter(ux, uy);
			gun = {8'h4D, i[0], 3'b000, 1'b0, 2'b00, cnt, 5'h1F};
			check({gun, {NBITS-40{1'b1}}}, "gun only");
			check_on(1, "gun only");
		end

		// 3. option button
		joystick_0 = BTN_B;
		frame();
		check({8'h4D, 1'b0, 3'b000, 1'b1, 2'b00, cnt, 5'h1F, {NBITS-40{1'b1}}}, "option");

		// 4. shot off screen: trigger, zero timer, zero hit count
		joystick_0 = BTN_C;
		frame();
		check({8'h4D, 1'b1, 3'b000, 1'b0, 2'b00, 20'd0, 5'h00, {NBITS-40{1'b1}}}, "off screen");

		// 5. the gun on joystick 1 followed by pad 1
		PAD_SEL = 1;
		GUN_SEL = 2;
		joystick_0 = 13'h0425;
		joystick_1 = BTN_A;
		joy0_x0 = to_axis(-118);
		joy0_y0 = to_axis(-108);
		joy1_x0 = to_axis(72);
		joy1_y0 = to_axis(-51);
		frame();
		check({8'h4D, 1'b1, 3'b000, 1'b0, 2'b00, ref_counter(72, -51), 5'h1F, ref_pad(13'h0425), {NBITS-56{1'b1}}}, "gun joy2 + pad");
		check_on(1, "gun joy2 + pad");
		checks = checks + 1;
		if (GUN_X !== ref_px(72, 319) || GUN_Y !== ref_px(-51, 239)) begin
			errors = errors + 1;
			$display("FAIL crosshair joy2: %0d,%0d", GUN_X, GUN_Y);
		end

		// 6. the gun on joystick 0 followed by two pads
		PAD_SEL = 2;
		GUN_SEL = 1;
		joystick_1 = 13'h0081;
		frame();
		check({8'h4D, 1'b0, 3'b000, 1'b1, 2'b00, ref_counter(-118, -108), 5'h1F, ref_pad(13'h0425), ref_pad(13'h0081), {NBITS-72{1'b1}}}, "gun joy1 + 2 pads");
		check_on(1, "gun joy1 + 2 pads");

		// 7. gun is not available with 3 pads
		PAD_SEL = 3;
		frame();
		check({NBITS{1'b1}}, "3 pads + gun");
		check_on(0, "3 pads + gun");

		// 8. arcade gun: trigger, service, coin, start
		PAD_SEL = 1;
		GUN_SEL = 0;
		ARCADE_SEL = 2;
		ARCADE_SERVICE = 1;
		joystick_0 = BTN_A | BTN_COIN;
		joystick_1 = 13'd0;
		frame();
		check({8'h4D, 1'b1, 1'b1, 1'b1, 1'b0, 1'b0, 2'b00, ref_counter(-118, -108), 5'h1F, {NBITS-40{1'b1}}}, "arcade gun coin");
		check_on(1, "arcade gun");
		ARCADE_SERVICE = 0;
		joystick_0 = BTN_START;
		frame();
		check({8'h4D, 1'b0, 1'b0, 1'b0, 1'b1, 1'b0, 2'b00, ref_counter(-118, -108), 5'h1F, {NBITS-40{1'b1}}}, "arcade gun start");

		// 9. arcade gun holstered
		joystick_0 = BTN_C;
		frame();
		check({8'h4D, 1'b0, 1'b0, 1'b0, 1'b0, 1'b1, 2'b00, ref_counter(-127, -127), 5'h00, {NBITS-40{1'b1}}}, "arcade gun holster");

		// 10. existing devices are unchanged with the gun off
		ARCADE_SEL = 0;
		PAD_SEL = 2;
		joystick_0 = 13'h0425;
		joystick_1 = 13'h0081;
		frame();
		check({ref_pad(13'h0425), ref_pad(13'h0081), {NBITS-32{1'b1}}}, "2 pads, gun off");
		check_on(0, "2 pads, gun off");
		ARCADE_SEL = 1;
		joystick_0 = BTN_START;
		joystick_1 = BTN_COIN;
		ARCADE_SERVICE = 1;
		frame();
		check({8'h49, 4'b0000, 20'd0, 8'hC0, 8'h00, 8'b00010011, 8'h00, {NBITS-64{1'b1}}}, "arcade trackball");
		check_on(0, "arcade trackball");

		// 11. PAL scan constants on the bus
		ARCADE_SEL = 0;
		ARCADE_SERVICE = 0;
		PAD_SEL = 0;
		GUN_SEL = 1;
		GUN_PAL = 1;
		joystick_0 = BTN_A;
		joy0_x0 = to_axis(127);
		joy0_y0 = to_axis(127);
		frame();
		check({8'h4D, 1'b1, 3'b000, 1'b0, 2'b00, ref_counter(127, 127), 5'h1F, {NBITS-40{1'b1}}}, "gun PAL");
		GUN_PAL = 0;
		GUN_SEL = 0;

		// 12. mouse: a button with the mouse still, then a fast movement in one read
		//     (three packets of +100/-90, doubled: +600/-540; a read takes up to 511)
		joystick_0 = 13'd0;
		MOUSE_EN = 1;
		ps2_mouse = {1'b0, 8'd0, 8'd0, 8'b00001001};       // left button, no packet
		frame();
		check({8'h49, 1'b1, 1'b0, 1'b0, 1'b0, 10'd0, 10'd0, {NBITS-32{1'b1}}}, "mouse button");
		for (i = 0; i < 3; i = i + 1) begin
			ps2_mouse = {~ps2_mouse[24], 8'd166, 8'd100, 8'b00101000};   // dx +100, dy -90 (sign bit set)
			repeat (4) @(posedge CLK);
		end
		frame();
		check({8'h49, 4'b0000, 10'd511, 10'd511, {NBITS-32{1'b1}}}, "mouse fast move");
		frame();
		check({8'h49, 4'b0000, 10'd29, 10'd89, {NBITS-32{1'b1}}}, "mouse remainder");
		frame();
		check({8'h49, 4'b0000, 10'd0, 10'd0, {NBITS-32{1'b1}}}, "mouse still");
		MOUSE_EN = 0;

		$display("checks=%0d errors=%0d", checks, errors);
		if (errors == 0) $display("TEST PASSED");
		else             $display("TEST FAILED");
		$finish;
	end

endmodule
